CREATE TABLE public.chip_ledger(id uuid,from_type text,from_entity_id uuid,to_type text,to_entity_id uuid,amount numeric(15,2),category text,club_id uuid,tournament_id uuid,created_at timestamp with time zone,idempotency_key text,pre_from_balance numeric,post_from_balance numeric,pre_to_balance numeric,post_to_balance numeric,status text,metadata jsonb,row_hash text);
CREATE TABLE public.chip_transactions(id uuid,club_id uuid,from_user_id uuid,to_user_id uuid,amount numeric(14,2),transaction_type text,metadata jsonb,created_at timestamp with time zone);
CREATE TABLE public.clubs(id uuid,union_id uuid,asset text,is_platform boolean);
CREATE TABLE public.poker_diamond_custody(id uuid,user_id uuid,arena_id uuid,purpose text,target_id uuid,entry_key text,balance bigint,state text,created_at timestamp with time zone,released_at timestamp with time zone,seat_id uuid,seat_joined_at timestamp with time zone,occupancy_id uuid);
CREATE TABLE public.poker_diamond_movements(request_id uuid,custody_id uuid,user_id uuid,action text,amount bigint,source_account text,destination_account text,wallet_journal_id uuid,request jsonb,receipt jsonb,created_at timestamp with time zone);
CREATE TABLE public.poker_diamond_tournament_ledger(id bigint,tournament_id uuid,arena_id uuid,user_id uuid,custody_id uuid,kind text,amount bigint,prize_part bigint,bounty_part bigint,fee_part bigint,idempotency_key text,wallet_journal_id uuid,obligation_id uuid,registration_id uuid,request jsonb,created_at timestamp with time zone);
CREATE TABLE public.tournament_participant_funding_receipts(id uuid,registration_id uuid,tournament_id uuid,user_id uuid,operation text,asset text,amount numeric,ledger_id uuid,funding_club_id uuid);
CREATE TABLE public.tournament_payouts(id uuid,tournament_id uuid,user_id uuid,amount numeric(15,2),source text,idempotency_key text,metadata jsonb);
CREATE TABLE public.tournament_refund_entitlements(id uuid,tournament_id uuid,user_id uuid,entitlement_kind text,charge_category text,refund_wallet_club_id uuid,gross numeric(15,2),refund_prize numeric(15,2),refund_bounty numeric(15,2),refund_fee numeric(15,2),source_ledger_id uuid,registration_id uuid,source_satellite_id uuid,source_ticket_id uuid,escrow_bucket text,evidence_kind text,created_at timestamp with time zone);
CREATE TABLE public.tournament_satellite_awards(tournament_id uuid,place integer,user_id uuid,delivery_kind text,amount numeric(15,2),payout_id uuid,payout_source text,idempotency_key text,registration_id uuid,ticket_id uuid);
CREATE TABLE public.tournament_satellite_settlements(tournament_id uuid,target_id uuid,pool numeric(15,2),target_buy_in numeric(15,2),target_fee numeric(15,2),ticket_cost numeric(15,2));
CREATE TABLE public.tournament_tickets(id uuid,club_id uuid,issued_by uuid,holder_id uuid,value numeric,status text,redeemed_at timestamp with time zone,redemption_mode text,source_tournament_id uuid,source_satellite_id uuid,source_refund_entitlement_id uuid,source_satellite_award_place integer,entry_prize numeric(15,2),entry_bounty numeric(15,2),entry_fee numeric(15,2));
CREATE TABLE public.tournaments(id uuid,buy_in_amount numeric(15,2),buy_in_fee numeric(15,2),club_id uuid,is_bounty boolean,bounty_amount numeric(15,2),is_pko boolean,is_mystery_bounty boolean,union_id uuid);
CREATE TABLE public.union_pnl_inventory_events(event_id bigint,source_name text,row_id uuid,after_row jsonb);
CREATE TABLE public.wallet_credit_idempotency(key text,user_id uuid,amount numeric,created_at timestamp with time zone);
